package com.wizzadrds.theworldremembers.voice; import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets; public final class LocalSpeechToText{private final Path executable;public LocalSpeechToText(Path executable){this.executable=executable;}public String transcribe(Path wav)throws IOException,InterruptedException{if(!Files.isRegularFile(wav))throw new FileNotFoundException(wav.toString());Process p=new ProcessBuilder(executable.toString(),wav.toAbsolutePath().toString()).redirectErrorStream(true).start();String out=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8).trim();int code=p.waitFor();if(code!=0)throw new IOException("Local STT exited with "+code);return out;}}